CREATE TABLE notifications(id BIGSERIAL PRIMARY KEY,recipient_user_id BIGINT,event_id UUID NOT NULL UNIQUE,type VARCHAR(100) NOT NULL,title VARCHAR(255) NOT NULL,message TEXT NOT NULL,reference_type VARCHAR(50),reference_id VARCHAR(100),read_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notification_deliveries(id BIGSERIAL PRIMARY KEY,notification_id BIGINT NOT NULL REFERENCES notifications(id),channel VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_notifications_recipient ON notifications(recipient_user_id,created_at DESC);
